        for (Owner other : ownerRepository.findAll()) {
            if (other.getCustomerCode() != null) {
                existing.add(other.getCustomerCode());
            }
        }
        owner.setCustomerCode(OwnerCustomerCode.deduplicate(base, existing));
    }
}

